const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cuttack = ee.Geometry.Point(85.87, 20.46).buffer(1000); // Cuttack, Odisha, 1km buffer

  const date1 = '2019-04-30';
  const date2 = '2019-05-04';

  // 2. Data Acquisition
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/VCMCFG_V1A_SVDNB');

  // Filter for the first date
  let collection1 = viirsCollection
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filterBounds(cuttack);

  // Filter for the second date
  let collection2 = viirsCollection
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filterBounds(cuttack);

  // Check collection sizes
  const size1 = await collection1.size().getInfo();
  const size2 = await collection2.size().getInfo();

  if (size1 === 0) {
    console.log(`No VIIRS DNB images found for ${date1}.`);
    console.log("C1");
    return;
  }
  if (size2 === 0) {
    console.log(`No VIIRS DNB images found for ${date2}.`);
    console.log("C1");
    return;
  }

  // Use the median image for each date to reduce noise and handle multiple images.
  const image1 = collection1.median();
  const image2 = collection2.median();

  // Cloud masking function: Mask pixels where cf_cvg is 1 (probably cloudy) or 2 (cloudy).
  // Only keep pixels with cf_cvg == 0 (clear).
  const cloudMask = function(image) {
    const cf_cvg = image.select('cf_cvg');
    return image.updateMask(cf_cvg.eq(0)); // Only keep clear pixels
  };

  const maskedImage1 = cloudMask(image1);
  const maskedImage2 = cloudMask(image2);

  // 3. Processing and Calculation
  const band = 'avg_rad'; // Average Radiance band
  const scale = 500; // Native resolution of VIIRS DNB is ~750m, use a slightly finer scale for region average

  // Reduce region for brightness and pixel count for the first date
  const result1 = await maskedImage1.select(band).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: cuttack,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16 // Increase tileScale for large regions or complex computations
  }).getInfo();

  const meanBrightness1 = result1 ? result1[band] : null;
  const pixelCount1 = result1 ? result1[band + '_count'] : 0;

  // Reduce region for brightness and pixel count for the second date
  const result2 = await maskedImage2.select(band).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: cuttack,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const meanBrightness2 = result2 ? result2[band] : null;
  const pixelCount2 = result2 ? result2[band + '_count'] : 0;

  // Validate pixel counts after masking
  if (pixelCount1 === 0 || pixelCount2 === 0) {
    console.log(`No valid (clear) pixels remaining after cloud masking for one or both dates. ${date1} Pixels: ${pixelCount1}, ${date2} Pixels: ${pixelCount2}.`);
    console.log("C2");
    return;
  }

  // 4. Validation & Final Answer
  if (meanBrightness1 === null || isNaN(meanBrightness1) ||
      meanBrightness2 === null || isNaN(meanBrightness2)) {
    console.log(`Calculation resulted in invalid brightness value. Brightness 1: ${meanBrightness1}, Brightness 2: ${meanBrightness2}.`);
    console.log("C3");
    return;
  }

  console.log(`${date1} Images: ${size1} (Clear Pixels: ${pixelCount1}, Brightness: ${meanBrightness1.toFixed(4)} nW/cm²/sr)`);
  console.log(`${date2} Images: ${size2} (Clear Pixels: ${pixelCount2}, Brightness: ${meanBrightness2.toFixed(4)} nW/cm²/sr)`);

  if (meanBrightness2 < meanBrightness1) {
    console.log("A"); // Brightness decreased
  } else {
    console.log("B"); // Brightness did not decrease (increased or stayed same)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
